-- NASDAQ 종목. db/generate-stock-seeds.sh 가 만든다 — 손으로 고치지 않는다.
-- 명세: docs/SPEC-stock-master.md
--
-- 선행: db/ddl-stocks-nullable.sql · db/ddl-markets-code-nyse.sql · db/seed-markets.sql
-- 여러 번 실행해도 결과가 같다 (on duplicate key update).

-- 이 파일은 UTF-8 이다. 클라이언트가 latin1 로 읽으면 한글이 이중 인코딩돼
-- 들어간다 — 삼성전자가 4자가 아니라 12자로 저장되고, 눈으로는 구분되지 않는다.
-- 실행 방식에 맡기지 않고 파일이 스스로 선언한다.
set names utf8mb4;

-- market_id 를 숫자로 박지 않는다 — 로컬과 서버의 auto_increment 가 다르다.
-- 시장이 없으면 @market 이 NULL 이 되고, market_id 가 NOT NULL 이라 곧바로 멈춘다.
set @market = (select market_id from markets
               where code = 'NASDAQ' and country = 'US'
               order by market_id limit 1);

insert into stocks (market_id, ticker, name, img_url, status, exchange,
                    float_shares, ceo, listed_at, created_at, updated_at)
